/* =============================================================================
   Column Control Component
   Layouts: 50/50 | 33/33/33 | 25/75 | 75/25 | 33/66 | 66/33
   ============================================================================= */
.columncontrol {
  display: flex;
  flex-wrap: nowrap;
  align-items: stretch !important;
  /* overridden by inline style from model */
  width: 100%;
  box-sizing: border-box;
}
.columncontrol__col {
  box-sizing: border-box;
  min-width: 0;
}
.columncontrol__col > .aem-Grid {
  display: flex;
  height: 100%;
  /* prevents flex blowout on long content */
}
/* ── Gutter ─────────────────────────────────────────────────────────────── */
.columncontrol--gutter {
  gap: 1.5rem;
}
/* =============================================================================
   Layout Variants
   ============================================================================= */
/* 50 / 50 */
.columncontrol--col-50-50 .columncontrol__col {
  flex: 0 0 50%;
  width: 50%;
}
/* 33 / 33 / 33 */
.columncontrol--col-33-33-33 .columncontrol__col {
  flex: 0 0 33.333%;
  width: 33.333%;
}
/* 25 / 75 */
.columncontrol--col-25-75 .columncontrol__col--1 {
  flex: 0 0 25%;
  width: 25%;
}
.columncontrol--col-25-75 .columncontrol__col--2 {
  flex: 0 0 75%;
  width: 75%;
}
/* 75 / 25 */
.columncontrol--col-75-25 .columncontrol__col--1 {
  flex: 0 0 75%;
  width: 75%;
}
.columncontrol--col-75-25 .columncontrol__col--2 {
  flex: 0 0 25%;
  width: 25%;
}
/* 33 / 66 */
.columncontrol--col-33-66 .columncontrol__col--1 {
  flex: 0 0 33.333%;
  width: 33.333%;
}
.columncontrol--col-33-66 .columncontrol__col--2 {
  flex: 0 0 66.666%;
  width: 66.666%;
}
/* 66 / 33 */
.columncontrol--col-66-33 .columncontrol__col--1 {
  flex: 0 0 66.666%;
  width: 66.666%;
}
.columncontrol--col-66-33 .columncontrol__col--2 {
  flex: 0 0 33.333%;
  width: 33.333%;
}
/* =============================================================================
   Gutter-aware width corrections (subtract gap from flex-basis)
   ============================================================================= */
.columncontrol--gutter.columncontrol--col-50-50 .columncontrol__col {
  flex: 0 0 calc(49.25%);
  width: calc(49.25%);
}
.columncontrol--gutter.columncontrol--col-33-33-33 .columncontrol__col {
  flex: 0 0 calc(32.333%);
  width: calc(32.333%);
}
/* =============================================================================
   Responsive — Stack on Mobile
   ============================================================================= */
@media only screen and (max-width: 576px), only screen and (min-width: 576px) and (max-width: 767px) {
  .columncontrol,
  .columncontrol--stack-mobile {
    flex-wrap: wrap;
  }
  .columncontrol .columncontrol__col,
  .columncontrol--stack-mobile .columncontrol__col {
    flex: 0 0 100% !important;
    width: 100% !important;
  }
  .columncontrol.columncontrol--gutter,
  .columncontrol--stack-mobile.columncontrol--gutter {
    gap: 1rem;
  }
}
